    mode_labels = dict(((key, _(label)) for key, label in warderPiconSync.UPDATE_MODES))
    labels = {'wp-pos': _('Satellite positions') + ': ' + position_text, 'wp-res': _('Picon resolution') + ': ' + (resolution.replace('x', ' x ') if resolution else _('No resolution selected')), 'wp-style': _('Picon colour') + ': ' + (_(style.capitalize()) if style else _('No colour selected')), 'wp-dest': _('Picon location') + ': ' + location, 'wp-mode': _('Update method') + ': ' + mode_labels.get(mode, _('No update method selected'))}
